[checks/watch_acceptance.py]
CASE normal paths, scoring, sorting and alerts
INPUT {"max_hops": 2, "routes": [{"assets": ["USDT"], "chains": ["eth"], "id": "r1", "min_score": 80, "severity": "critical", "target": "ops"}, {"assets": ["*"], "chains": ["*"], "id": "r2", "min_score": 100, "severity": "warning", "target": "sec"}, {"assets": ["*"], "chains": ["polygon"], "id": "r3", "min_score": 100, "severity": "info", "target": "none"}], "scoring": {"fan_out_recipients": 2}, "transfers": [{"amount": 2, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "t1", "timestamp": "2026-01-01T00:00:00Z", "to_address": "B", "usd_value": 100}, {"amount": 3, "asset": "USDT", "chain": "eth", "from_address": "B", "id": "t2", "timestamp": "2026-01-01T00:01:00Z", "to_address": "D", "usd_value": 200}, {"amount": 4, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "t3", "timestamp": "2026-01-01T00:02:00Z", "to_address": "B", "usd_value": 300}, {"amount": 5, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "t4", "timestamp": "2026-01-01T00:03:00Z", "to_address": "C", "usd_value": 400}, {"amount": 6, "asset": "USDT", "chain": "eth", "from_address": "C", "id": "t5", "timestamp": "2026-01-01T00:04:00Z", "to_address": "D", "usd_value": 500}, {"amount": 7, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "t6", "timestamp": "2026-01-01T00:05:00Z", "to_address": "D", "usd_value": 600}], "watch_addresses": ["A", "B", "D"], "whale_threshold_usd": 100}
OUTPUT {"data": {"paths": [{"nodes": ["A", "B", "D"], "transfer_ids": ["t3", "t2"], "hops": 2, "amount": 7, "usd_value": 500, "from_address": "A", "to_address": "D", "chain": "eth", "asset": "USDT", "path_id": "t3>t2", "score": 100, "reason": ["VALUE", "FAN_OUT"]}, {"nodes": ["A", "C", "D"], "transfer_ids": ["t4", "t5"], "hops": 2, "amount": 11, "usd_value": 900, "from_address": "A", "to_address": "D", "chain": "eth", "asset": "USDT", "path_id": "t4>t5", "score": 100, "reason": ["VALUE", "FAN_OUT"]}, {"nodes": ["A", "B", "D"], "transfer_ids": ["t1", "t2"], "hops": 2, "amount": 5, "usd_value": 300, "from_address": "A", "to_address": "D", "chain": "eth", "asset": "USDT", "path_id": "t1>t2", "score": 80, "reason": ["VALUE", "FAN_OUT"]}, {"nodes": ["A", "B"], "transfer_ids": ["t3"], "hops": 1, "amount": 4, "usd_value": 300, "from_address": "A", "to_address": "B", "chain": "eth", "asset": "USDT", "path_id": "t3", "score": 60, "reason": ["VALUE", "FAN_OUT"]}, {"nodes": ["A", "B"], "transfer_ids": ["t1"], "hops": 1, "amount": 2, "usd_value": 100, "from_address": "A", "to_address": "B", "chain": "eth", "asset": "USDT", "path_id": "t1", "score": 40, "reason": ["VALUE", "FAN_OUT"]}, {"nodes": ["B", "D"], "transfer_ids": ["t2"], "hops": 1, "amount": 3, "usd_value": 200, "from_address": "B", "to_address": "D", "chain": "eth", "asset": "USDT", "path_id": "t2", "score": 40, "reason": ["VALUE"]}, {"nodes": ["A", "D"], "transfer_ids": ["t6"], "hops": 1, "amount": 7, "usd_value": 600, "from_address": "A", "to_address": "D", "chain": "eth", "asset": "USDT", "path_id": "t6", "score": 40, "reason": ["VALUE"]}], "alerts": [{"route_id": "r1", "path_id": "t1>t2", "from_address": "A", "to_address": "D", "chain": "eth", "asset": "USDT", "severity": "critical", "score": 80, "reason": ["VALUE", "FAN_OUT"], "target": "ops"}, {"route_id": "r1", "path_id": "t3>t2", "from_address": "A", "to_address": "D", "chain": "eth", "asset": "USDT", "severity": "critical", "score": 100, "reason": ["VALUE", "FAN_OUT"], "target": "ops"}, {"route_id": "r1", "path_id": "t4>t5", "from_address": "A", "to_address": "D", "chain": "eth", "asset": "USDT", "severity": "critical", "score": 100, "reason": ["VALUE", "FAN_OUT"], "target": "ops"}, {"route_id": "r2", "path_id": "t3>t2", "from_address": "A", "to_address": "D", "chain": "eth", "asset": "USDT", "severity": "warning", "score": 100, "reason": ["VALUE", "FAN_OUT"], "target": "sec"}, {"route_id": "r2", "path_id": "t4>t5", "from_address": "A", "to_address": "D", "chain": "eth", "asset": "USDT", "severity": "warning", "score": 100, "reason": ["VALUE", "FAN_OUT"], "target": "sec"}]}}
CASE cross chain and asset isolation with empty result
INPUT {"max_hops": 2, "routes": [], "transfers": [{"amount": 1, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "x1", "timestamp": "2026-01-01T00:00:00Z", "to_address": "B", "usd_value": 100}, {"amount": 1, "asset": "USDT", "chain": "polygon", "from_address": "B", "id": "x2", "timestamp": "2026-01-01T00:01:00Z", "to_address": "D", "usd_value": 100}, {"amount": 1, "asset": "USDC", "chain": "eth", "from_address": "B", "id": "x3", "timestamp": "2026-01-01T00:02:00Z", "to_address": "D", "usd_value": 100}], "watch_addresses": ["A", "D"], "whale_threshold_usd": 100}
