INPUT {"max_hops": 2, "routes": [], "transfers": [{"amount": 1, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "p1", "timestamp": "2026-01-01T00:00:00Z", "to_address": "B", "usd_value": 100}, {"amount": 2, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "p2", "timestamp": "2026-01-01T00:01:00Z", "to_address": "B", "usd_value": 200}, {"amount": 3, "asset": "USDT", "chain": "eth", "from_address": "B", "id": "p3", "timestamp": "2026-01-01T00:02:00Z", "to_address": "D", "usd_value": 300}, {"amount": 4, "asset": "USDT", "chain": "eth", "from_address": "D", "id": "p4", "timestamp": "2026-01-01T00:03:00Z", "to_address": "B", "usd_value": 400}], "watch_addresses": ["A", "D"], "whale_threshold_usd": 100}
OUTPUT {"data": {"paths": [{"nodes": ["A", "B", "D"], "transfer_ids": ["p2", "p3"], "hops": 2, "amount": 5, "usd_value": 500, "from_address": "A", "to_address": "D", "chain": "eth", "asset": "USDT", "path_id": "p2>p3", "score": 80, "reason": ["VALUE"]}, {"nodes": ["A", "B", "D"], "transfer_ids": ["p1", "p3"], "hops": 2, "amount": 4, "usd_value": 400, "from_address": "A", "to_address": "D", "chain": "eth", "asset": "USDT", "path_id": "p1>p3", "score": 60, "reason": ["VALUE"]}], "alerts": []}}
