INPUT {"max_hops": 1, "routes": [], "transfers": [{"amount": 1, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "p1", "timestamp": "2026-01-01T00:00:00Z", "to_address": "B", "usd_value": 100}, {"amount": 2, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "p2", "timestamp": "2026-01-01T00:01:00Z", "to_address": "B", "usd_value": 200}, {"amount": 3, "asset": "USDT", "chain": "eth", "from_address": "B", "id": "p3", "timestamp": "2026-01-01T00:02:00Z", "to_address": "D", "usd_value": 300}, {"amount": 4, "asset": "USDT", "chain": "eth", "from_address": "D", "id": "p4", "timestamp": "2026-01-01T00:03:00Z", "to_address": "B", "usd_value": 400}], "watch_addresses": ["A", "D"], "whale_threshold_usd": 100}
OUTPUT {"data": {"paths": [], "alerts": []}}
CASE amount and usd_value use ten-decimal aggregation
INPUT {"max_hops": 2, "routes": [], "transfers": [{"amount": 0.1, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "q1", "timestamp": "2026-01-01T00:00:00Z", "to_address": "B", "usd_value": 0.1}, {"amount": 0.2, "asset": "USDT", "chain": "eth", "from_address": "B", "id": "q2", "timestamp": "2026-01-01T00:01:00Z", "to_address": "D", "usd_value": 0.2}], "watch_addresses": ["A", "D"], "whale_threshold_usd": 1}
