CASE reason order and segment scoring
INPUT {"max_hops": 1, "routes": [], "scoring": {"burst_count": 5, "fan_out_points": 20, "fan_out_recipients": 5, "round_trip_points": 40, "transfer_burst_points": 30, "value_points_cap": 10, "value_points_per_ratio": 1, "window_seconds": 3600}, "transfers": [{"amount": 1, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "s1", "timestamp": "2026-01-01T00:00:00Z", "to_address": "B", "usd_value": 100}, {"amount": 1, "asset": "USDT", "chain": "eth", "from_address": "B", "id": "s2", "timestamp": "2026-01-01T00:01:00Z", "to_address": "A", "usd_value": 100}, {"amount": 1, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "s3", "timestamp": "2026-01-01T00:02:00Z", "to_address": "C", "usd_value": 100}, {"amount": 1, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "s4", "timestamp": "2026-01-01T00:03:00Z", "to_address": "D", "usd_value": 100}, {"amount": 1, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "s5", "timestamp": "2026-01-01T00:04:00Z", "to_address": "E", "usd_value": 100}, {"amount": 1, "asset": "USDT", "chain": "eth", "from_address": "A", "id": "s6", "timestamp": "2026-01-01T00:05:00Z", "to_address": "F", "usd_value": 100}], "watch_addresses": ["A", "B"], "whale_threshold_usd": 100}
OUTPUT {"data": {"paths": [{"nodes": ["A", "B"], "transfer_ids": ["s1"], "hops": 1, "amount": 1, "usd_value": 100, "from_address": "A", "to_address": "B", "chain": "eth", "asset": "USDT", "path_id": "s1", "score": 91, "reason": ["VALUE", "BURST", "FAN_OUT", "ROUND_TRIP"]}, {"nodes": ["B", "A"], "transfer_ids": ["s2"], "hops": 1, "amount": 1, "usd_value": 100, "from_address": "B", "to_address": "A", "chain": "eth", "asset": "USDT", "path_id": "s2", "score": 41, "reason": ["VALUE", "ROUND_TRIP"]}], "alerts": []}}
